use vstd::prelude::*;

verus! {

pub fn bmat(
    top_left: Vec<f32>,
    top_right: Vec<f32>,
    bottom_left: Vec<f32>,
    bottom_right: Vec<f32>,
) -> (result: Vec<f32>)
    requires
        top_right.len() == top_left.len(),
        bottom_left.len() == top_left.len(),
        bottom_right.len() == top_left.len(),
        // capacity computation must not overflow `usize`
        4usize * top_left.len() <= usize::MAX,
    ensures
        result.len() == 4 * top_left.len(),
        // result is the concatenation of the four blocks in order
        forall|i: int|
            0 <= i < top_left.len() ==> result[i] == top_left[i],
        forall|i: int|
            0 <= i < top_left.len() ==> result[top_left.len() + i] == top_right[i],
        forall|i: int|
            0 <= i < top_left.len() ==> result[2 * top_left.len() + i] == bottom_left[i],
        forall|i: int|
            0 <= i < top_left.len() ==> result[3 * top_left.len() + i] == bottom_right[i],
{
    let n = top_left.len();
    debug_assert_eq!(top_right.len(), n);
    debug_assert_eq!(bottom_left.len(), n);
    debug_assert_eq!(bottom_right.len(), n);

    let mut result = Vec::with_capacity(4 * n);

    // Help Verus track length evolution through the pushes.
    assert(result.len() == 0);
    result.extend_from_slice(&top_left);
    assert(result.len() == n);

    result.extend_from_slice(&top_right);
    assert(result.len() == 2 * n);

    result.extend_from_slice(&bottom_left);
    assert(result.len() == 3 * n);

    result.extend_from_slice(&bottom_right);
    assert(result.len() == 4 * n);

    result
}

} // verus!